alter table schedule_solve_jobs enable row level security;alter table schedule_solve_attempts enable row level security;drop policy if exists schedule_solve_jobs_tenant_read on schedule_solve_jobs;create policy schedule_solve_jobs_tenant_read on schedule_solve_jobs for select to authenticated using(institution_code=current_tenant_code());drop policy if exists schedule_solve_attempts_tenant_read on schedule_solve_attempts;create policy schedule_solve_attempts_tenant_read on schedule_solve_attempts for select to authenticated using(exists(select 1 from schedule_solve_jobs j where j.id=job_id and j.institution_code=current_tenant_code()));revoke all on schedule_solve_jobs,schedule_solve_attempts,schedule_compute_workers from anon;revoke insert,update,delete,truncate,references,trigger on schedule_solve_jobs,schedule_solve_attempts,schedule_compute_workers from authenticated;grant select on schedule_solve_jobs,schedule_solve_attempts to authenticated;